mapper.select:
SELECT 
FROM cps_area_person_config
WHERE 1 = 1

  AND factory = #{factory}


  AND area = #{area}


  AND enabled = #{enabled}

ORDER BY factory ASC, area ASC, line ASC, process ASC, id ASC

mapper.update:
UPDATE cps_area_person_config
SET enabled = #{enabled},
    updated_by = #{updatedBy}
WHERE id = #{id}

mapper.select:
SELECT process AS value,
       process AS label
FROM cps_area_person_config
WHERE enabled = 1
  AND process != ''
  AND factory = #{factory}
  AND area = #{area}

  AND line = #{line}

GROUP BY factory, area, line, process
ORDER BY process ASC
